export default async function sync(
  { body, baseId, siteId, ackSubmissionId, ackResolution },
  context,
) {
  const s = (await context.state.get("webflow-airtable-progress")) ?? {
    queue: [],
    seen: [],
    pending: null,
  };
  if (!Array.isArray(s.queue) || !Array.isArray(s.seen)) throw Error("Invalid submission state");
  if (body !== null) {
    const p = body?.payload;
    if (
      body?.triggerType !== "form_submission" ||
      !p ||
      p.siteId !== siteId ||
      ![p.id, p.formId, p.name, p.submittedAt].every((v) => typeof v === "string" && v.trim()) ||
      !p.data ||
      typeof p.data !== "object" ||
      Array.isArray(p.data)
    )
      throw Error("Invalid Webflow form submission");
    if (!s.seen.includes(p.id) && !s.queue.some((x) => x.id === p.id)) s.queue.push(p);
    await context.state.set("webflow-airtable-progress", s);
  }
  if (s.pending) {
    if (ackSubmissionId !== s.pending.id)
      throw Error(
        "Pending submission " +
          s.pending.id +
          " at " +
          s.pending.stage +
          ": inspect Airtable before resolving",
      );
    if (s.queue[0]?.id !== s.pending.id) throw Error("Pending queue mismatch");
    if (ackResolution === "completed") {
      s.seen.push(s.pending.id);
      s.queue.shift();
    } else if (ackResolution !== "retry")
      throw Error(
        "Choose completed after manually storing the submission, or retry after ensuring no duplicate",
      );
    s.pending = null;
    await context.state.set("webflow-airtable-progress", s);
  }
  if (!s.queue.length) return { processed: 0 };
  if (typeof baseId !== "string" || !baseId || typeof siteId !== "string" || !siteId)
    throw Error("Configure Airtable base and Webflow site");
  let count = 0;
  const action = async (name, input) => context.actions.call(name, input),
    pending = async (id, stage, tableId) => {
      s.pending = { id, stage, ...(tableId ? { tableId } : {}) };
      await context.state.set("webflow-airtable-progress", s);
    },
    clear = async () => {
      s.pending = null;
      await context.state.set("webflow-airtable-progress", s);
    },
    fields = (names) =>
      names.map((name) => ({ name, type: name === "FormContent" ? "richText" : "singleLineText" }));
  while (s.queue.length) {
    const p = s.queue[0],
      schema = await action("airtable.get_base_schema", { baseId });
    if (!Array.isArray(schema?.tables)) throw Error("Missing base schema");
    let tables = schema.tables,
      index = tables.filter(
        (t) => typeof t.name === "string" && t.name.toLowerCase() === "form index",
      );
    if (index.length > 1) throw Error("Multiple Form Index tables");
    let indexId = index[0]?.id;
    if (!indexId) {
      await pending(p.id, "create-index-table");
      const r = await action("airtable.create_table", {
        baseId,
        name: "Form Index",
        fields: fields(["FormId", "FormName", "TableId", "TableName"]),
      });
      indexId = r?.id;
      if (typeof indexId !== "string" || !indexId) throw Error("Index creation returned no ID");
      await clear();
    }
    const escaped = p.formId.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
    const found = await action("airtable.list_records", {
      baseId,
      tableIdOrName: indexId,
      filterByFormula: "{FormId}='" + escaped + "'",
      maxRecords: 2,
    });
    if (!Array.isArray(found?.records)) throw Error("Missing index records");
    if (found.records.length > 1) throw Error("Duplicate form index entries");
    let tableId = found.records[0]?.fields?.TableId;
    if (found.records.length && !tableId) throw Error("Index entry has no table ID");
    if (tableId && !tables.some((t) => t.id === tableId))
      throw Error("Indexed form table no longer exists");
    if (!tableId) {
      await pending(p.id, "create-form-table");
      const t = await action("airtable.create_table", {
        baseId,
        name: p.name,
        fields: fields(["Id", "FormId", "FormName", "FormCreationDate", "FormContent"]),
      });
      tableId = t?.id;
      if (typeof tableId !== "string" || !tableId)
        throw Error("Form table creation returned no ID");
      await pending(p.id, "write-index", tableId);
      await action("airtable.create_records", {
        baseId,
        tableIdOrName: indexId,
        records: [
          { fields: { FormId: p.formId, FormName: p.name, TableId: tableId, TableName: p.name } },
        ],
        typecast: false,
        returnFieldsByFieldId: false,
      });
      await clear();
    }
    await pending(p.id, "write-submission");
    await action("airtable.create_records", {
      baseId,
      tableIdOrName: tableId,
      records: [
        {
          fields: {
            Id: p.id,
            FormId: p.formId,
            FormName: p.name,
            FormCreationDate: p.submittedAt,
            FormContent: JSON.stringify(p.data),
          },
        },
      ],
      typecast: false,
      returnFieldsByFieldId: false,
    });
    s.seen.push(p.id);
    s.queue.shift();
    s.pending = null;
    await context.state.set("webflow-airtable-progress", s);
    count++;
  }
  return { processed: count };
}
